import{_ as n,C as t,o as i,c as s,a6 as r,E as o}from"./chunks/framework.CKIbuWFA.js";const m=JSON.parse('{"title":"Install and manage plugins","description":"","frontmatter":{"title":"Install and manage plugins","docId":"user.plugins.index","translationKey":"user.plugins.index","locale":"en","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"93c8811682d0baa5bd18b571503fce483cf1f464e94b94bc933241bf277d23d4","translationRevision":"93c8811682d0baa5bd18b571503fce483cf1f464e94b94bc933241bf277d23d4","order":10},"headers":[],"relativePath":"en/user/plugins/index.md","filePath":"en/user/plugins/index.md","lastUpdated":1794591482000}'),l={name:"en/user/plugins/index.md"};function d(c,e,u,p,g,h){const a=t("DemoFrame");return i(),s("div",null,[e[0]||(e[0]=r('<h1 id="install-and-manage-plugins" tabindex="-1">Install and manage plugins <a class="header-anchor" href="#install-and-manage-plugins" aria-label="Permalink to &quot;Install and manage plugins {#install-and-manage-plugins}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Goal and prerequisites {#goal-and-prerequisites}&quot;">​</a></h2><p>Add an integration, review its requested access and confirm that its actions are usable. You need a desktop package compatible with the plugin&#39;s operating system, architecture and host version. Remote catalog and download operations require network access; some account-based services also require <a href="./../cloud/account.html">Cloud sign-in</a>.</p><h2 id="review-before-enabling" tabindex="-1">Review before enabling <a class="header-anchor" href="#review-before-enabling" aria-label="Permalink to &quot;Review before enabling {#review-before-enabling}&quot;">​</a></h2><ol><li>Open <strong>Plugins</strong> and inspect Installed, Explore or Updates. Explore requests plugin entries only. Find automation templates and profiles in <a href="./../automations/templates.html">Automations</a>.</li><li>Select a plugin to inspect its description, version, compatibility and runtime. Check the publisher and requested capabilities or permissions rather than trusting a familiar display name alone.</li><li>Use the install flow to inspect the package preview. Review the exact version, signature information, requested access and changes from an installed version before confirming installation.</li><li>Wait for the package job result. Downloading, installing and enabling are distinct stages; a catalog card alone does not mean the runtime is ready.</li><li>Open the plugin&#39;s Settings or Connection pane. Supply its service address and credentials only in the intended fields. Use a declared connection check when offered.</li><li>Enable the plugin, then check whether its action types or pages appear. Create a narrowly scoped <a href="./../automations/first-rule.html">logging rule</a> before attaching a powerful external action.</li></ol><p>Plugins can run native code or separate processes. A process boundary can isolate a crash, but it is not an operating system sandbox. Install software from publishers you trust. A valid signature identifies reviewed package provenance; it does not make every effect appropriate for your workflow.</p><h2 id="expected-result-and-status" tabindex="-1">Expected result and status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Expected result and status {#expected-result-and-status}&quot;">​</a></h2><p>Package review, installation jobs, plugin preferences and version management are available. Actual actions depend on the installed manifest, host capabilities and external service. Event processors have their own panel and can add optional analysis fields to events; raw fields remain distinct.</p><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recovery {#recovery}&quot;">​</a></h2><p>For installation failure, read the job error for compatibility, signature, runtime or download problems. Do not weaken verification just to clear an error. If an update causes trouble, inspect retained versions and use rollback where available. Review dependent automations before disabling or uninstalling a plugin. Keep <a href="./../preferences/backups.html">backups</a> of plugin data and configuration before removing them.</p>',10)),o(a,{scenario:"plugins",locale:"en",tour:"plugin",title:"Demo: plugins"})])}const b=n(l,[["render",d]]);export{m as __pageData,b as default};
